<?php
declare(strict_types=1);
require __DIR__.'/stage31_fixtures.php';
use Berserk\Core\{Engine,StrikeResolver,InstantProcessor,WoundTransferProcessor,InformationalWaitManager};
use Berserk\Core\Choice\ValhallaPickChoice;
s31test('R1 reduce attacker final damage',function(){$s=s31state();s31combat($s);$s->battle['strike']['instant_stack']=[s31item(3,'host',['type'=>'strike_level','mode'=>'reduce_one'],'value')];s31resolve($s);s31check($s->battle['strike']['result']['attack']==='medium'&&$s->getCard(2)->hp===17,'reduce must survive recalc and deal 3');s31ack($s);s31check($s->getCard(2)->hp===17,'ACK not duplicate');return ['target_hp'=>17];});
s31test('R1 defender set final answer damage',function(){$s=s31state();s31combat($s,4,2);$s->battle['strike']['instant_stack']=[s31item(91,'player',['type'=>'strike_level','mode'=>'set','value'=>'strong'],'power')];s31resolve($s);s31check($s->getCard(1)->hp===16&&$s->getCard(2)->hp===17,'defender strong=4, attacker medium=3');return ['attacker_hp'=>16,'target_hp'=>17];});
s31test('R1 attacker set final damage',function(){$s=s31state();s31combat($s,2);$s->battle['strike']['instant_stack']=[s31item(3,'host',['type'=>'strike_level','mode'=>'set','value'=>'strong'],'power')];s31resolve($s);s31check($s->getCard(2)->hp===16,'set strong=4');return ['target_hp'=>16];});
s31test('R1 multiple phases power then value',function(){$s=s31state();s31combat($s,2);$s->battle['strike']['instant_stack']=[s31item(3,'host',['type'=>'strike_level','mode'=>'reduce_one'],'value',2),s31item(90,'host',['type'=>'strike_level','mode'=>'set','value'=>'strong'],'power',1)];s31resolve($s);s31check($s->getCard(2)->hp===17,'strong then reduce=medium');$sum=$s->battle['strike']['instant_summary'];s31check(array_column($sum,'phase')===['power','value'],'phase order preserved');return ['phases'=>array_column($sum,'phase'),'hp'=>17];});
s31test('R1 same phase LIFO two reductions',function(){$s=s31state();s31combat($s);$s->battle['strike']['instant_stack']=[s31item(3,'host',['type'=>'strike_level','mode'=>'reduce_one'],'value',0),s31item(90,'host',['type'=>'strike_level','mode'=>'reduce_one'],'value',1)];s31resolve($s);s31check($s->getCard(2)->hp===18,'two reductions weak=2');s31check(array_column($s->battle['strike']['instant_summary'],'sequence')===[1,0],'LIFO');return ['hp'=>18,'sequence'=>[1,0]];});
foreach(['before','after']as$order)s31test('R1 redirect '.$order.' level change',function()use($order){$s=s31state();s31combat($s);$e=new Engine();$reduce=fn()=>$e->applyCombatEffect($s,['type'=>'strike_level','mode'=>'reduce_one'],$s->getCard(3),'host');$redirect=fn()=>$e->applyCombatEffect($s,['type'=>'redirect_strike'],$s->getCard(2),'player',null,$s->getCard(4));if($order==='before'){$reason=$redirect();$reduce();}else{$reduce();$reason=$redirect();}s31check($reason===null,'redirect legal');(new StrikeResolver($s,$e))->recalcTable();s31check($s->battle['strike']['target_id']===4&&$s->battle['strike']['result']['attack']==='medium','redirect must retain reduction');(new StrikeResolver($s,$e))->apply($s->battle['strike']['result'],false);s31check($s->getCard(4)->hp===17&&$s->getCard(2)->hp===20,'new target gets medium once');return ['new_target_hp'=>17,'old_target_hp'=>20];});
s31test('R1 dice changes baseline before levels',function(){$s=s31state();s31combat($s,2);$e=new Engine();$e->applyCombatEffect($s,['type'=>'dice_choice'],$s->getCard(3),'host','plus:own');$e->applyCombatEffect($s,['type'=>'dice_choice'],$s->getCard(3),'host','plus:own');$e->applyCombatEffect($s,['type'=>'strike_level','mode'=>'reduce_one'],$s->getCard(3),'host');(new StrikeResolver($s,$e))->recalcTable();s31check($s->battle['strike']['attack_dice']===4&&$s->battle['strike']['result']['attack']==='weak','medium reduced weak after dice');return ['dice'=>4,'result'=>'weak'];});
s31test('R1 repeated recalc after persistence not repeated reduction',function(){$s=s31state();s31combat($s);$e=new Engine();$e->applyCombatEffect($s,['type'=>'strike_level','mode'=>'reduce_one'],$s->getCard(3),'host');$s=s31roundtrip($s);for($i=0;$i<3;$i++)(new StrikeResolver($s,new Engine()))->recalcTable();s31check($s->battle['strike']['result']['attack']==='medium','not cumulatively reduced');return ['recalcs'=>3,'result'=>'medium'];});
s31test('R1 set does not freeze defender recomputation',function(){$s=s31state();s31combat($s,4,2);$e=new Engine();$e->applyCombatEffect($s,['type'=>'strike_level','mode'=>'set','value'=>'strong'],$s->getCard(3),'host');$s->battle['strike']['defend_dice']=4;(new StrikeResolver($s,$e))->recalcTable();s31check($s->battle['strike']['result']['attack']==='strong'&&$s->battle['strike']['result']['defend']==='','defend baseline must update');return ['result'=>$s->battle['strike']['result']];});

foreach(['source','amount','target','target_amount']as$step)s31test('R2 combat cancel at '.$step,function()use($step){$s=s31wounds();if($step!=='source')s31ok($s,'host','wt_source',['donor_id'=>1]);if(in_array($step,['target','target_amount'],true))s31ok($s,'host','wt_amount',['amount'=>2]);if($step==='target_amount')s31ok($s,'host','wt_target',['target_id'=>90]);s31check($s->battle['pending_wound_transfer']['step']===$step,'selected stage');s31ok($s,'host','cancel_pending');s31check(empty($s->battle['pending_wound_transfer'])&&empty($s->battle['strike']),'queue and combat settle');s31check($s->getCard(1)->hp===18&&$s->getCard(90)->hp===20,'existing wounds unchanged');s31check(!$s->getCard(3)->closed,'cancel reopens source');$r=s31cmd($s,'host','cancel_pending');s31check(!$r->success&&$s->getCard(1)->hp===18,'retry not applied');return ['donor_hp'=>18,'source_closed'=>false,'combat_cleared'=>true];});
s31test('R2 main phase cancel refunds once',function(){$s=s31state();$s->getCard(1)->hp=18;$s->getCard(3)->coins=3;$p=new WoundTransferProcessor($s,new Engine());s31check($p->start('host',$s->getCard(3),['coins_cost'=>2,'on_finish'=>'main_phase'])->success,'WT start');s31check($s->getCard(3)->coins===1,'cost paid');$s=s31roundtrip($s);s31ok($s,'host','cancel_pending');s31check($s->getCard(3)->coins===3&&!$s->getCard(3)->closed,'refund and reopen');s31cmd($s,'host','cancel_pending');s31check($s->getCard(3)->coins===3,'no second refund');return ['coins'=>3];});
s31test('R2 resume next wound item without replaying earlier summary',function(){$s=s31wounds();$next=s31item(90,'host',['type'=>'redistribute_wounds'],'wounds',1);$s->battle['strike']['instant_resolution']['queue'][]=$next;s31ok($s,'host','cancel_pending');s31check(($s->battle['pending_wound_transfer']['source_id']??0)===90,'next item owns pending');s31check(count($s->battle['strike']['instant_summary'])===2,'earlier + one cancelled summary');s31check(count($s->battle['strike']['instant_resolution']['queue'])===1&&$s->battle['strike']['instant_resolution']['queue'][0]['card_id']===90&&$s->battle['strike']['instant_summary'][0]['effect_type']==='earlier','neighbour and earlier summary preserved');s31ok($s,'host','cancel_pending');s31check(empty($s->battle['strike'])&&$s->getCard(1)->hp===18,'both skipped no repeated damage');return ['donor_hp'=>18,'next_source'=>90];});

foreach([false,true]as$double)s31test('R3 cancel first '.($double?'double':'ordinary').' activation',function()use($double){$s=s31valhalla($double);s31ok($s,'host','cancel_pending');s31check(empty($s->battle['pending_valhalla_pick'])&&$s->getCard(2)->hp===20,'no effect applied');if($double)s31check(!empty($s->getCard(3)->flags['ragnar_valhalla_double_used_this_turn']),'repeat not refunded');s31check(!s31cmd($s,'host','cancel_pending')->success,'repeat cancel rejected');return ['hp'=>20,'double'=>$double];});
s31test('R3 cancel second preserves first and spent repeat',function(){$s=s31valhalla();s31ok($s,'host','valhalla_pick',['target_id'=>2]);s31check($s->getCard(2)->hp===19&&$s->battle['pending_valhalla_pick']['repeat_index']===2,'first completed');s31ok($s,'host','cancel_pending');s31check($s->getCard(2)->hp===19&&$s->getCard(4)->hp===20&&empty($s->battle['pending_valhalla_pick']),'remainder cancelled only');s31check(!empty($s->getCard(3)->flags['ragnar_valhalla_double_used_this_turn']),'repeat spent');return ['first_hp'=>19,'other_hp'=>20];});
s31test('R3 choose two different targets',function(){$s=s31valhalla();s31ok($s,'host','valhalla_pick',['target_id'=>2]);s31ok($s,'host','valhalla_pick',['target_id'=>4]);s31check($s->getCard(2)->hp===19&&$s->getCard(4)->hp===19&&empty($s->battle['pending_valhalla_pick']),'two picks');return ['hp'=>[19,19]];});
s31test('R3 no candidates after activation can cancel',function(){$s=s31valhalla();foreach([2,4,91]as$id)$s->removeCard($id);s31ok($s,'host','cancel_pending');s31check(empty($s->battle['pending_valhalla_pick']),'stale candidates not stuck');return ['cleared'=>true];});
s31test('R3 wrong owner cannot cancel',function(){$s=s31valhalla();$before=$s->battle['pending_valhalla_pick'];s31check(!s31cmd($s,'player','cancel_pending')->success,'wrong owner denied');s31check($s->battle['pending_valhalla_pick']===$before,'pending intact');return ['denied'=>true];});
s31test('R3 cancel releases phase subtask',function(){$s=s31valhalla();$s->battle['turn_phase']=['phase'=>'start','side'=>'active','active_key'=>'host','passive_key'=>'player','active_queue'=>[],'passive_queue'=>[],'sub'=>['parent_type'=>'valhalla','remaining'=>[['id'=>'v5','card_id'=>5]],'pending_id'=>'v5']];s31ok($s,'host','cancel_pending');s31check(empty($s->battle['turn_phase']),'phase resumed');return ['phase_cleared'=>true];});
s31test('R3 UI cancel maps to supported command',function(){$s=s31valhalla();$h=new ValhallaPickChoice();$spec=$h->spec($s,'host',[],'/test','host');s31check(in_array('cancel_pending',$h->commandTypes(),true),'command supported');s31check(str_contains(json_encode($spec->buttons),'cancel_pending'),'UI offers cancel');return ['cancel_supported'=>true];});

s31test('H1 voluntary end then immediate end_turn no card action',function(){s31roll();$s=s31state(['attack_series'=>true,'unanswer'=>true]);s31ok($s,'host','strike',['card_id'=>1,'target_id'=>2]);s31ack($s);s31check(!empty($s->battle['pending_attack_series_choice']),'next pick');$first=json_encode($s->toArray());s31trace($s,'H1-after-first-battle');s31ok($s,'host','attack_series_end');$closed=json_encode($s->toArray());s31check($s->getCard(1)->closed&&empty($s->battle['pending_attack_series_choice'])&&empty($s->battle['strike']),'series ends');s31trace($s,'H1-after-end');s31ok($s,'host','end_turn');s31trace($s,'H1-after-end-turn');for($i=0;$i<10&&!empty($s->battle['turn_phase']);$i++){ $tp=$s->battle['turn_phase'];s31check(!empty($tp['pending_ack']),'unexpected phase decision');s31ok($s,$tp[$tp['side'].'_key'],'turn_ack');}s31check($s->battle['active']==='player'&&empty($s->battle['turn_phase']),'turn completed');s31check($s->getCard(2)->hp===16&&$s->getCard(4)->hp===20,'no second attack');s31check(!json_decode($first,true)['cards'][1]['closed']&&json_decode($closed,true)['cards'][1]['closed'],'closed change real, old copy unchanged');s31trace($s,'H1-next-player-ready');return ['closed_at_first_battle'=>false,'closed_after_end'=>true,'closed_next_turn'=>$s->getCard(1)->closed,'target_hp'=>16];});
s31test('H1 natural series end includes closing',function(){s31roll();$s=s31state(['attack_series'=>true,'unanswer'=>true]);$s->getCard(4)->row=5;$s->getCard(4)->col=5;s31ok($s,'host','strike',['card_id'=>1,'target_id'=>2]);s31ack($s);s31check($s->getCard(1)->closed&&empty($s->battle['pending_attack_series_choice']),'natural end closed');return ['closed'=>true];});
s31test('H1 dead Hydra does not continue',function(){s31roll('1,6');$s=s31state(['attack_series'=>true]);$s->getCard(1)->hp=1;$s->getCard(2)->closed=false;s31ok($s,'host','strike',['card_id'=>1,'target_id'=>2]);s31ack($s);s31check($s->getCard(1)->zone==='graveyard'&&empty($s->battle['pending_attack_series_choice']),'dead source done');return ['zone'=>'graveyard'];});
s31test('H1 winner during series no manufactured cleanup',function(){s31roll();$s=s31state(['attack_series'=>true,'unanswer'=>true]);$s->removeCard(4);$s->removeCard(91);$s->getCard(2)->hp=1;s31ok($s,'host','strike',['card_id'=>1,'target_id'=>2]);s31check($s->status==='game_over'&&$s->winner==='host','winner');s31check(!s31cmd($s,'host','attack_series_next',['target_id'=>2])->success,'cannot continue terminal');return ['status'=>$s->status,'strike_remaining'=>!empty($s->battle['strike'])];});
s31test('R1 dice pending resume and final damage once',function(){$s=s31state();s31combat($s,3);unset($s->battle['strike']['combat_instant_window']);$s->battle['strike']['instant_stack']=[s31item(3,'host',['type'=>'dice_choice'],'dice'),s31item(90,'host',['type'=>'strike_level','mode'=>'reduce_one'],'value')];(new InstantProcessor($s,new Engine()))->resolveStack();s31check(!empty($s->battle['pending_dice_choice']),'paused at dice');$s=s31roundtrip($s);s31ok($s,'host','choose_dice_choice',['choice'=>'plus:own']);s31check($s->getCard(2)->hp===18&&$s->battle['strike']['attack_dice']===4,'medium reduced weak deals 2');s31check(count($s->battle['strike']['instant_summary'])===2,'each item summarized once');s31check(!s31cmd($s,'host','choose_dice_choice',['choice'=>'plus:own'])->success,'duplicate choice denied');s31check($s->getCard(2)->hp===18,'no extra wounds');return ['dice'=>4,'hp'=>18,'summaries'=>2];});
s31test('R1 legacy attacker override retains value and new reduction',function(){$s=s31state();s31combat($s,2);$s->battle['strike']['result']['attack']='strong';$s->battle['strike']['level_overridden']=true;(new Engine())->applyCombatEffect($s,['type'=>'strike_level','mode'=>'reduce_one'],$s->getCard(3),'host');$s=s31roundtrip($s);(new StrikeResolver($s,new Engine()))->recalcTable();s31check($s->battle['strike']['result']['attack']==='medium','legacy set then reduce');return ['result'=>'medium'];});
s31test('R3 first lethal application no candidates no second repeat',function(){$s=s31valhalla();$s->removeCard(4);$s->removeCard(91);$s->getCard(2)->hp=1;s31ok($s,'host','valhalla_pick',['target_id'=>2]);s31check($s->status==='game_over'&&$s->getCard(2)->zone==='graveyard'&&empty($s->battle['pending_valhalla_pick']),'terminal no remaining repeat');s31check(!s31cmd($s,'host','cancel_pending')->success,'no terminal cancellation');return ['status'=>'game_over','zone'=>'graveyard'];});
s31test('Review R1 exact metadata roundtrip and pure recalc',function(){$s=s31state();s31combat($s);$e=new Engine();$e->applyCombatEffect($s,['type'=>'strike_level','mode'=>'reduce_one'],$s->getCard(3),'host');$base=$s->battle['strike']['base_result'];$changes=$s->battle['strike']['strike_level_effects'];$s=s31roundtrip($s);s31check($s->battle['strike']['base_result']===$base&&$s->battle['strike']['strike_level_effects']===$changes,'exact metadata roundtrip');for($i=0;$i<2;$i++)(new StrikeResolver($s,new Engine()))->recalcTable();s31check($s->battle['strike']['base_result']['attack']==='strong'&&$s->battle['strike']['result']['attack']==='medium','base remains separate');s31check($s->battle['strike']['strike_level_effects']===$changes&&empty($s->battle['strike']['instant_summary'])&&$s->getCard(2)->hp===20,'pure recalc no new effects summaries or wounds');return ['base'=>'strong','result'=>'medium','effects'=>count($changes),'hp'=>20];});
s31test('Review R2 mismatched queue item cannot be cancelled',function(){$s=s31wounds();$s->battle['strike']['instant_resolution']['queue'][0]['card_id']=90;$before=$s->toArray();$r=s31cmd($s,'host','cancel_pending');s31check(!$r->success,'mismatched queue denied');s31check($s->battle['pending_wound_transfer']===$before['battle']['pending_wound_transfer']&&$s->battle['strike']['instant_resolution']===$before['battle']['strike']['instant_resolution'],'pending and neighbour preserved');s31check($s->getCard(3)->coins===$before['cards']['3']['coins'],'no refund');return ['rejected'=>true,'queue_preserved'=>true];});
$output=getenv('STAGE31_RESULTS');if($output){file_put_contents($output,json_encode(['results'=>$results,'traces'=>$traces],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));}
foreach($results as$r)echo $r['status'].' '.$r['case'].' '.json_encode($r['detail']??$r['error'],JSON_UNESCAPED_UNICODE)."\n";
exit(count(array_filter($results,fn($r)=>$r['status']==='FAIL'))?1:0);
